export const createClassList = (classes) => {
    if (classes !== undefined) {
        const array = Array.isArray(classes) ? classes : classes.split(' ');
        return array
            .filter((c) => c != null)
            .map((c) => c.trim())
            .filter((c) => c !== '');
    }
    return [];
};
export const createClassMap = (classes) => {
    const map = {};
    createClassList(classes).forEach((c) => (map[c] = true));
    return map;
};
